css:
:root{font:13px/1.45 -apple-system,BlinkMacSystemFont,"PingFang SC",system-ui,sans-serif;color:#263952;background:#fff;color-scheme:light;--space-1:4px;--space-2:8px;--space-3:12px;--space-4:16px;--radius-control:8px;--radius-surface:12px;--od-icon-size:34px;--od-ink:#263952;--od-sub:#576982;--od-line:#dce4ef;--od-paper:#fff;--od-bg:#f7f9fc;--od-brand:#365ed3;--od-negative:#a03a43}
*{box-sizing:border-box}body{margin:0}button,input,textarea,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.43;cursor:default}[hidden]{display:none!important}
.cookie-app{width:100%;min-width:0;margin:0;padding:var(--space-3);display:flex;flex-direction:column;gap:var(--space-3)}
.site-bar,.toolbar,.section-head,.form-actions,.footer-actions{display:flex;align-items:center;gap:var(--space-2);min-width:0}
.site-bar{border-bottom:1px solid var(--od-line);padding-bottom:var(--space-3)}
.site-meta{display:grid;gap:var(--space-1);min-width:0;flex:1}.site-meta strong{display:block;max-width:100%;font-size:13px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.secondary{color:var(--od-sub);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.icon-button{display:grid;place-items:center;flex:none;width:var(--od-icon-size);height:var(--od-icon-size);border:1px solid var(--od-line);border-radius:var(--radius-control);background:var(--od-paper);color:#506783;padding:0}
.icon-button svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.icon-button:hover:not(:disabled),.text-button:hover:not(:disabled){background:#edf3ff}
:focus-visible{outline:2px solid var(--od-brand);outline-offset:2px}
.permission-help{margin:0;padding:var(--space-3);border:1px solid #c6d6f6;border-radius:var(--radius-control);background:#f2f6ff;color:#304c7d;font-size:12px}
.cookie-content{display:grid;min-width:0;gap:var(--space-2)}.search-field{flex:1;min-width:0}.export-actions{flex-wrap:wrap;gap:var(--space-2)}.fill{flex:1;min-width:0}.count{color:var(--od-sub);font-size:12px;white-space:nowrap}
input[type=text],input[type=password],input[type=url],input[type=search],input[type=datetime-local],textarea,select{display:block;min-width:0;width:100%;min-height:36px;padding:var(--space-2);border:1px solid #c9d5e6;border-radius:var(--radius-control);background:#fff;color:var(--od-ink)}
input[type=file]{min-width:0;width:100%;max-width:100%;font-size:12px}.export-actions select{width:auto;max-width:145px;min-width:92px}textarea{line-height:1.5;resize:vertical;overflow-wrap:anywhere}
.text-button{min-height:36px;padding:var(--space-2) var(--space-3);border-radius:var(--radius-control);border:1px solid var(--od-line);background:#fff;color:var(--od-ink);white-space:nowrap}.text-button.primary{background:var(--od-brand);color:#fff;border-color:var(--od-brand)}.text-button.primary:hover:not(:disabled){background:#2b53bc}
.danger-text{color:var(--od-negative)}.danger-button{color:#fff;background:var(--od-negative);border-color:var(--od-negative)}.danger-button:hover:not(:disabled){background:#852b35}
.cookie-list{display:grid;gap:var(--space-2);min-width:0}.cookie-row{min-width:0;padding:var(--space-3);display:grid;gap:var(--space-2);border:1px solid var(--od-line);border-radius:var(--radius-surface);background:#fff}
.cookie-row-head{display:flex;align-items:flex-start;gap:var(--space-2);min-width:0}.cookie-row-title{display:grid;gap:var(--space-1);min-width:0;flex:1}.cookie-row-name{font-size:13px;font-weight:650;overflow-wrap:anywhere}
.cookie-row-meta{color:var(--od-sub);font-size:11px;line-height:1.4;overflow-wrap:anywhere;word-break:break-word}
.cookie-row-value{max-width:100%;min-width:0;padding:var(--space-2);border-radius:var(--radius-control);background:var(--od-bg);font:12px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere;word-break:break-all;white-space:pre-wrap}
.cookie-row-actions{display:flex;justify-content:flex-end;gap:var(--space-2);flex-wrap:wrap}.row-action{font-size:12px;border:1px solid var(--od-line);border-radius:var(--radius-control);min-height:34px;padding:var(--space-1) var(--space-2);background:#fff;color:var(--od-ink)}.row-action:hover:not(:disabled){background:#edf3ff}.row-action.delete{color:var(--od-negative)}
.empty-message{font-size:12px;color:var(--od-sub);padding:var(--space-4) var(--space-2);text-align:center;border:1px dashed var(--od-line);border-radius:var(--radius-control);margin:0}.footer-actions{justify-content:flex-end;border-top:1px solid #edf0f6;padding-top:var(--space-2)}
.editor-panel{display:grid;gap:var(--space-3);padding:var(--space-3);border:1px solid var(--od-line);border-radius:var(--radius-surface);background:var(--od-bg)}.section-head{justify-content:space-between}.section-head strong{font-size:13px}
#editor-form{display:grid;gap:var(--space-3)}.field{display:grid;gap:var(--space-2);min-width:0}.field label{font-weight:600;font-size:12px}.field-grid,.flag-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--space-3)}
.check-label{display:flex;align-items:center;gap:var(--space-2);min-width:0;overflow-wrap:anywhere;font-size:12px;color:#40546f}.check-label input{margin:0;accent-color:var(--od-brand);flex:none}.field input:read-only{background:#f0f2f7;color:#52657d}
.hint{margin:0;color:var(--od-sub);font-size:12px;overflow-wrap:anywhere}.form-actions{justify-content:flex-end;flex-wrap:wrap}.form-actions .text-button{min-width:72px}
.confirmation{padding:var(--space-3);border:1px solid #ecc9ce;border-radius:var(--radius-surface);background:#fff7f8}.confirmation p{font-size:13px;margin:0 0 var(--space-3)}
.status{margin:0;color:#45627f;font-size:12px;line-height:1.45;overflow-wrap:anywhere}.status[data-state=error]{color:var(--od-negative)}.status[data-state=success]{color:#20684f}
.visually-hidden{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;clip-path:inset(50%)}
@media(max-width:360px){.field-grid,.flag-grid{grid-template-columns:minmax(0,1fr)}.export-actions select{max-width:114px}}
@media(prefers-reduced-motion:no-preference){.icon-button,.text-button,.row-action{transition:background .12s ease}}

/* Sandbox theme matches R27 dimensions; this is not a second privileged design system. */
.preview-banner{margin:0;padding:var(--space-3);border:1px solid #bfd3f2;border-radius:var(--radius-control);background:#eff5ff;color:#2f517c;font-size:12px;line-height:1.5;overflow-wrap:anywhere}
.sample-button{justify-self:center;white-space:normal}

/* Real Chrome is the default task. Offline file editing stays accessible
   but no longer occupies a full primary navigation row. */
.workspace-options{min-width:0;border-top:1px solid var(--od-line);padding-top:var(--space-2)}
.workspace-options summary{cursor:pointer;max-width:100%;font-size:12px;color:var(--od-sub);font-weight:500;overflow-wrap:anywhere}
.workspace-options[open] summary{margin-bottom:var(--space-2)}
.workspace-options summary:focus-visible{outline:2px solid var(--od-brand);outline-offset:2px}
/* Browser/Offline are distinct modes: no offline row is styled as a Chrome result. */
.mode-tabs{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--space-1);padding:4px;border-radius:var(--radius-control);background:var(--od-bg)}
.mode-button{min-width:0;min-height:36px;padding:var(--space-2);border:1px solid transparent;border-radius:6px;color:var(--od-sub);background:transparent;font-weight:600;white-space:normal}
.mode-button.active{background:var(--od-paper);border-color:var(--od-line);color:var(--od-ink);box-shadow:0 1px 2px #233a5b12}
.browser-panel{display:grid;gap:var(--space-3);min-width:0}
.target-selector{min-width:0;padding:var(--space-2) 0;border-bottom:1px solid var(--od-line)}
.target-selector summary{cursor:pointer;color:var(--od-sub);font-size:12px;font-weight:600}
.target-selector[open] summary{margin-bottom:var(--space-2)}
.target-selector>label{display:block;margin-bottom:var(--space-2);font-size:12px;font-weight:600}
.target-entry{display:flex;align-items:center;gap:var(--space-2);min-width:0;flex-wrap:wrap}
.target-entry input{flex:1 1 180px;min-width:0}
.target-entry button{flex:0 0 auto}
.browser-state{min-width:0;padding:var(--space-3);border:1px solid var(--od-line);border-radius:var(--radius-surface);background:var(--od-bg)}
.browser-state strong{display:block;font-size:13px}.browser-state p{margin:var(--space-1) 0 0;font-size:12px;color:var(--od-sub);overflow-wrap:anywhere}
.live-toolbar{justify-content:flex-end;gap:var(--space-2);flex-wrap:nowrap}
.live-section-title{display:flex;align-items:baseline;flex-wrap:wrap;flex:1 1 auto;gap:var(--space-1);min-width:0;font-size:12px;font-weight:600}.live-section-title .count{min-width:0;white-space:normal;overflow-wrap:anywhere}
.live-toolbar .fill{display:none}.live-toolbar .icon-button{width:34px;height:34px;flex:0 0 34px}
#live-cookie-list .cookie-row{padding:var(--space-2) var(--space-3);gap:var(--space-1)}
.cookie-row-trigger{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2);width:100%;min-width:0;border:0;background:transparent;padding:var(--space-1) 0;color:var(--od-ink);text-align:left}
.cookie-row-trigger:hover:not(:disabled) .cookie-row-name{color:var(--od-brand)}
.cookie-row-trigger .cookie-row-name{min-width:0;flex:1;font-size:13px;line-height:1.4}
.row-chevron{flex:none;width:16px;height:16px;color:var(--od-sub);transition:transform .12s ease}
.cookie-row-trigger[aria-expanded=true] .row-chevron{transform:rotate(180deg)}
.cookie-row-expanded{border-color:#b2c5e8;background:var(--od-paper)}
#editor-panel.cookie-inline{margin-top:var(--space-2);padding:var(--space-3) 0 0;border:0;border-top:1px solid var(--od-line);border-radius:0;background:transparent}
.inline-operation{min-width:0}.inline-operation p{overflow-wrap:anywhere}
.sensitive-note{margin:0;font-size:12px;line-height:1.5;color:var(--od-negative);overflow-wrap:anywhere}
.import-preview{margin:0;padding:var(--space-3);border:1px solid var(--od-line);border-radius:var(--radius-control);background:var(--od-paper);color:var(--od-ink);font-size:12px;line-height:1.55;overflow-wrap:anywhere;white-space:pre-line;max-height:320px;overflow-y:auto}
#browser-import-slot,#offline-import-slot,#offline-editor-slot,#browser-editor-slot{min-width:0}
#browser-editor-slot{display:grid;gap:var(--space-2);padding:var(--space-3);border:1px solid var(--od-line);border-radius:var(--radius-surface);background:var(--od-bg)}
.permission-details{padding:var(--space-2) var(--space-3);border:1px solid var(--od-line);border-radius:var(--radius-control);color:var(--od-sub);font-size:12px}
.permission-details summary{cursor:pointer;color:var(--od-ink);font-weight:600}.permission-details p{margin:var(--space-2) 0 0;overflow-wrap:anywhere}
#live-cookie-list .cookie-row{gap:var(--space-1)}
@media(max-width:340px){.target-entry input{flex-basis:100%}.target-entry button{flex:1}}
@media(min-width:800px){.cookie-app{max-width:760px;margin-inline:auto}}
.live-filters{flex-wrap:wrap}.live-filters input{flex:1 1 150px}.live-filters select{width:auto;min-width:94px;max-width:120px}

/* Browser Cookie action controls reuse R27 spacing and compact button styles. */
.browser-advanced-actions{display:flex;flex-wrap:wrap;align-items:center;gap:var(--space-2);margin-top:var(--space-3)}
.browser-advanced-actions select{width:auto;max-width:125px;min-width:94px}
.browser-observe{margin-top:var(--space-3);border-top:1px solid var(--od-line);padding-top:var(--space-3)}
.browser-observe summary{cursor:pointer}.browser-observe .cookie-row{font-size:12px}
@media(max-width:320px){.browser-advanced-actions>*{flex:1 1 auto}}

@media(prefers-color-scheme:dark){
  :root{color-scheme:dark;background:#142033;color:#e5edfa;--od-ink:#e5edfa;--od-sub:#b3c1d6;--od-line:#3a4c65;--od-paper:#1e2b40;--od-bg:#16243a;--od-brand:#8badff;--od-negative:#ffacb3}
  .cookie-row,.text-button,.icon-button,.row-action,.mode-button.active,.confirmation{background:var(--od-paper);color:var(--od-ink);border-color:var(--od-line)}
  .cookie-row-trigger{color:var(--od-ink)}
  input[type=text],input[type=password],input[type=url],input[type=search],input[type=datetime-local],textarea,select{background:var(--od-paper);color:var(--od-ink);border-color:var(--od-line)}
  .field input:read-only{background:#263752;color:#d1dcef}
  .permission-help,.preview-banner{background:#223554;color:#dbe9ff;border-color:#475f84}
  .cookie-row-expanded{border-color:#708bc2}
  .text-button.primary{color:white;background:#365ed3;border-color:#365ed3}
  .danger-button{color:white;background:#a03a43;border-color:#a03a43}
  .row-action:hover:not(:disabled),.icon-button:hover:not(:disabled),.text-button:hover:not(:disabled){background:#2d3e5b}
  .text-button.primary:hover:not(:disabled){background:#2747aa}
  .cookie-row-value{background:#152236}
}

/* R4.3: compact daily-use list, current-site card, inline editing. */
.cookie-app{padding:10px 12px 14px;gap:10px}
.site-bar{display:flex;gap:9px;align-items:center;background:var(--od-bg);border:0;border-radius:10px;padding:10px 9px;min-width:0}
.site-icon{display:grid;place-items:center;width:32px;height:32px;flex:none;border-radius:9px;background:#e7eeff;color:#365ed3}
.site-icon svg,.site-pick svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.site-meta{flex:1;min-width:0;gap:0}
.site-eyebrow{font-size:11px;color:var(--od-sub)}
.site-pick{display:flex;align-items:center;gap:3px;max-width:100%;min-width:0;padding:0;border:0;background:transparent;color:var(--od-ink);text-align:left}
.site-pick strong{min-width:0;max-width:100%;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.site-pick svg{width:13px;height:13px;flex:none}
.site-pick:disabled{opacity:.6}
.site-grant-status{font-size:11px;color:var(--od-sub);white-space:nowrap}
.site-grant-status[data-state=ready]{color:#258067}
.site-bar #refresh{width:30px;height:30px;border:0;background:transparent}
#target-selector{margin-top:-8px;padding:0 2px 10px;border-bottom:0}
#target-selector:not([open]){display:none}
#target-selector[open]{background:var(--od-bg);border-radius:8px;padding:10px}
#target-selector[open] summary{margin-bottom:8px}
.browser-panel{gap:9px}
.live-toolbar{min-height:37px;gap:3px;margin-top:5px}
.live-section-title{font-size:13px;font-weight:700}
.live-section-title .count{font-size:12px;font-weight:400;color:var(--od-sub)}
.live-toolbar .icon-button{width:32px;height:32px;border:0;border-radius:7px;background:transparent}
.live-toolbar #live-new{color:var(--od-brand)}
.live-action-divider{width:1px;height:19px;flex:none;background:var(--od-line);margin:0 5px}
.live-filters{min-width:0}
.live-search-row{display:flex;align-items:center;gap:6px}
.live-search-box{position:relative;flex:1;min-width:0}
.live-search-box svg{position:absolute;left:10px;top:9px;width:16px;height:16px;fill:none;stroke:var(--od-sub);stroke-width:1.7;stroke-linecap:round;pointer-events:none}
.live-search-box input{width:100%;height:36px;padding-left:34px}
.live-search-row #live-filter-toggle{border:1px solid var(--od-line)}
.live-filter-advanced{display:grid;grid-template-columns:auto minmax(0,1fr) auto minmax(0,1fr);gap:6px;align-items:center;background:var(--od-bg);padding:8px;border-radius:8px;margin-top:7px}
.live-filter-advanced label{font-size:11px;color:var(--od-sub)}
.live-filter-advanced select{width:100%;min-width:0}
#live-cookie-list{display:block;border-top:1px solid var(--od-line);margin-inline:-12px}
#live-cookie-list .cookie-row{display:grid;gap:0;min-height:58px;margin:0;padding:8px 12px 9px;border:0;border-bottom:1px solid var(--od-line);border-radius:0;background:var(--od-paper)}
#live-cookie-list .cookie-row-trigger{padding:3px 0 0;min-height:26px}
#live-cookie-list .cookie-row-name{font-size:13px;font-weight:680}
#live-cookie-list .cookie-row-meta{display:block;padding:0 23px 1px 0;font-size:11px;line-height:1.45;color:var(--od-sub);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#live-cookie-list .cookie-row-expanded{background:var(--od-bg)}
#editor-panel.cookie-inline{margin:9px -4px 0;padding:10px;border:1px solid #b5c8ec;border-left:3px solid var(--od-brand);border-radius:8px;background:var(--od-paper)}
#editor-panel.cookie-inline #editor-form{gap:10px}
#editor-panel.cookie-inline .field{gap:5px}
#editor-panel.cookie-inline #editor-help{font-size:11px}
#live-export-panel,#browser-import-slot:not([hidden])>.editor-panel{padding:12px;border-radius:10px;background:var(--od-bg)}
#browser-editor-slot{padding:10px;background:var(--od-bg);border:1px solid var(--od-line);border-radius:8px}
.permission-details{border:0;border-top:1px solid var(--od-line);border-radius:0;padding:9px 0;color:var(--od-sub)}
.permission-details summary{font-size:12px;font-weight:500}
@media(max-width:350px){.live-filter-advanced{grid-template-columns:auto minmax(0,1fr)}}
@media(prefers-color-scheme:dark){
 .site-icon{background:#263754;color:#aabfff}
 .site-grant-status[data-state=ready]{color:#88cdb1}
 #live-cookie-list .cookie-row{background:var(--od-paper)}
 #live-cookie-list .cookie-row-expanded{background:var(--od-bg)}
 #editor-panel.cookie-inline{background:var(--od-paper);border-color:#637eae}
 .live-toolbar .icon-button{background:transparent}
}

/* R4.4: approved R4.3 product surface, excluding its demonstration frame. */
:root{--od-sub:#75839a;--od-line:#e5eaf2}
.cookie-app{padding:13px 14px 20px;gap:10px;line-height:1.5}
.site-bar{padding:10px 11px;gap:10px}
.site-grant-status{flex:none;max-width:72px}
.live-toolbar{margin-top:7px;min-height:34px}
.live-toolbar .icon-button{width:34px;height:34px}
.live-section-title .count{font-size:13px}
.live-search-box input{border-color:var(--od-line);font-size:12px}
.live-filter-advanced{display:grid;grid-template-columns:minmax(0,1fr);gap:8px;padding:7px 9px;background:var(--od-bg);border-radius:8px}
.live-filter-chips{display:flex;gap:6px;flex-wrap:wrap}
.live-filter-chip{padding:4px 8px;min-height:27px;border:1px solid var(--od-line);border-radius:7px;background:var(--od-paper);color:var(--od-sub);font-size:11px}
.live-filter-chip.sel{background:#f0f5ff;color:var(--od-brand);border-color:#b7c7f2}
.live-filter-sort{display:flex;justify-self:end;width:min(100%,200px);gap:8px;align-items:center}
.live-filter-sort label{font-size:11px;color:var(--od-sub);flex:none}
.live-filter-sort select{min-height:30px;width:auto;flex:1;font-size:11px}
#live-cookie-list{margin-inline:-14px}
#live-cookie-list .cookie-row{padding:0;min-height:61px;gap:0}
#live-cookie-list .cookie-row-trigger{display:flex;align-items:center;gap:7px;width:100%;min-height:61px;padding:11px 14px;text-align:left}
#live-cookie-list .cookie-row-title{display:grid;gap:2px;flex:1;min-width:0}
#live-cookie-list .cookie-row-name{font-weight:680;font-size:13px;line-height:1.35;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#live-cookie-list .cookie-row-meta{padding:0;font-size:11px;line-height:1.5;color:var(--od-sub);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#live-cookie-list .cookie-row-tag{font-size:10px;line-height:1.45;color:var(--od-sub);background:var(--od-bg);border-radius:5px;padding:3px 5px;white-space:nowrap}
#live-cookie-list .cookie-row-expanded{background:linear-gradient(to right,#f0f5ff,var(--od-paper) 12%)}
#live-cookie-list .cookie-row-trigger:hover:not(:disabled){background:#f7faff}
#editor-panel.cookie-inline{margin:0 10px 10px;padding:12px;border:1px solid var(--od-line);border-left:2px solid var(--od-brand);border-radius:9px;background:var(--od-paper);gap:10px}
#editor-panel.cookie-inline #editor-form{gap:10px}
.editor-top-tip{margin:0;padding:6px 8px;border-radius:6px;font-size:11px;color:#258067;background:#edf8f4}
.cookie-advanced{border-top:1px solid var(--od-line);padding-top:5px}
.cookie-advanced summary{cursor:pointer;color:var(--od-sub);font-size:11px;font-weight:680}
.cookie-advanced-fields{display:grid;gap:10px;margin-top:9px}
.cookie-advanced-fields .field-grid{gap:7px}
.cookie-advanced-fields .flag-grid{gap:10px}
.cookie-advanced-fields .field label{font-size:11px}
.cookie-advanced .field-note,.field-note{font-size:10.5px;line-height:1.55;color:var(--od-sub)}
.value-label{display:flex;justify-content:space-between;align-items:center;gap:6px}
.reveal-value-button{border:0;background:transparent;color:var(--od-brand);padding:1px 0;font-size:11px}
.revealed-cookie-value{display:block;background:var(--od-bg);border:1px solid var(--od-line);border-radius:7px;padding:7px;font:11px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere;white-space:pre-wrap}
.editor-delete{margin-right:auto;color:var(--od-negative)}
.browser-list-hint{font-size:11px;line-height:1.6;margin:0;color:var(--od-sub)}
